-- Northwind Cloud: a fictional B2B SaaS company used as Glassbox demo data.
-- All names, emails and numbers are generated by supabase/seed.ts.

create schema if not exists northwind;

create table northwind.plans (
  id                  smallint primary key,
  name                text not null unique,
  tier                text not null check (tier in ('free', 'starter', 'team', 'business', 'enterprise')),
  monthly_price_cents integer not null check (monthly_price_cents >= 0),
  is_legacy           boolean not null default false
);

create table northwind.organizations (
  id         integer primary key,
  name       text not null,
  industry   text not null,
  country    text not null,
  timezone   text not null,
  created_at timestamptz not null,
  is_test    boolean not null default false
);

create table northwind.users (
  id           integer primary key,
  org_id       integer not null references northwind.organizations (id),
  email        text not null unique,
  role         text not null check (role in ('owner', 'admin', 'member', 'viewer')),
  created_at   timestamptz not null,
  last_seen_at timestamptz,
  is_internal  boolean not null default false
);

create table northwind.subscriptions (
  id            integer primary key,
  org_id        integer not null references northwind.organizations (id),
  plan_id       smallint references northwind.plans (id), -- NULL for grandfathered contracts
  status        text not null check (status in ('trialing', 'active', 'past_due', 'canceled')),
  started_at    timestamptz not null,
  canceled_at   timestamptz,
  cancel_reason text check (cancel_reason in ('churn', 'upgrade', 'downgrade')),
  mrr_cents     integer not null check (mrr_cents >= 0)
);

create table northwind.invoices (
  id              integer primary key,
  org_id          integer not null references northwind.organizations (id),
  subscription_id integer not null references northwind.subscriptions (id),
  amount_cents    integer not null, -- negative for refunds
  status          text not null check (status in ('paid', 'open', 'void')),
  issued_at       timestamptz not null,
  paid_at         timestamptz
);

create table northwind.events (
  id          bigint primary key,
  user_id     integer not null references northwind.users (id),
  org_id      integer not null references northwind.organizations (id),
  type        text not null check (type in ('login', 'feature_used')),
  feature     text, -- NULL for logins
  occurred_at timestamptz not null
);

create table northwind.support_tickets (
  id          integer primary key,
  org_id      integer not null references northwind.organizations (id),
  user_id     integer references northwind.users (id),
  category    text not null,
  priority    text check (priority in ('low', 'normal', 'high', 'urgent')), -- NULL when filed by email
  created_at  timestamptz not null,
  resolved_at timestamptz
);

create index on northwind.users (org_id);
create index on northwind.subscriptions (org_id);
create index on northwind.invoices (org_id, issued_at);
create index on northwind.events (occurred_at);
create index on northwind.events (org_id, occurred_at);
create index on northwind.events (user_id, occurred_at);
create index on northwind.support_tickets (created_at);

comment on schema northwind is 'Fictional demo data for Glassbox. Not a real company.';
